import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { strToU8, zipSync } from "fflate";
import type { Browser } from "playwright";
import { bgzfWrite } from "./io/bgzf.ts";

const vcf =
  "##fileformat=VCFv4.2\n##reference=GRCh38\n##contig=<ID=1,length=248956422>\n" +
  "#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\tFORMAT\tSAMPLE\n" +
  "1\t100\trs100\tC\tT\t100\tPASS\t.\tGT\t0/1\n";
const consumer =
  "# This data file is generated by 23andMe.\n# reference assembly build 37; plus strand\n" +
  "# rsid\tchromosome\tposition\tgenotype\nrs100\t1\t100\tCT\n";

function compressedVcf() {
  const directory = fs.mkdtempSync(path.join(os.tmpdir(), "genomewalk-browser-intake-"));
  try {
    const destination = path.join(directory, "synthetic.bgz");
    bgzfWrite(vcf, destination);
    return fs.readFileSync(destination);
  } finally {
    fs.rmSync(directory, { recursive: true });
  }
}

/** Synthetic files only; app/data requests remain local and telemetry is disabled on localhost. */
export async function checkIntake(browser: Browser, origin: string) {
  const context = await browser.newContext({ serviceWorkers: "block", reducedMotion: "reduce" });
  const page = await context.newPage();
  page.setDefaultTimeout(30_000);
  const failures: string[] = [];
  page.on("pageerror", (error) => failures.push(`Uncaught intake error: ${error.message}`));
  await context.route("**/*", async (route) => {
    const request = route.request();
    const url = new URL(request.url());
    if (url.origin === origin) {
      await route.continue();
      return;
    }
    if (
      (url.hostname === "fonts.googleapis.com" && request.resourceType() === "stylesheet") ||
      (url.hostname === "fonts.gstatic.com" && request.resourceType() === "font")
    ) {
      await route.abort("blockedbyclient");
      return;
    }
    failures.push(`Unexpected external intake request: ${url.hostname}${url.pathname}`);
    await route.abort("blockedbyclient");
  });
  const choose = (name: string, buffer: Buffer) =>
    page.locator('input[type="file"]').setInputFiles({
      name,
      mimeType: "application/octet-stream",
      buffer,
    });
  async function chapter() {
    await page.waitForURL(`${origin}/chapter/1`);
    await page.getByRole("heading", { name: "The file introduces itself", exact: true }).waitFor();
    await page.getByRole("button", { name: "Run this chapter", exact: true }).click();
    await page.getByRole("link", { name: "Next chapter", exact: true }).waitFor();
    assert.equal(await page.getByRole("alert").count(), 0, "Valid intake produced an error");
    assert.deepEqual(failures, []);
  }
  async function rejection(name: string, contents: Record<string, Uint8Array>, guidance: RegExp) {
    await choose(name, Buffer.from(zipSync(contents)));
    const alert = page.getByRole("alert").filter({ hasText: guidance });
    await alert.waitFor();
    assert.match(await alert.innerText(), guidance);
    assert.equal(
      await page.getByRole("button", { name: "Choose genome file", exact: true }).isEnabled(),
      true,
      "A rejected archive must leave file selection usable",
    );
  }
  try {
    const bytes = compressedVcf();
    for (const name of ["synthetic.gvcf.gz", "synthetic.gz"]) {
      await page.goto(origin, { waitUntil: "networkidle" });
      await choose(name, bytes);
      await chapter();
    }
    await page.goto(origin, { waitUntil: "networkidle" });
    await rejection(
      "documentation.zip",
      { "README.txt": strToU8("This is documentation, not a raw DNA export.") },
      /No supported DNA text file.*original raw 23andMe or AncestryDNA TXT export/s,
    );
    await rejection(
      "vcf-in-zip.zip",
      { "synthetic.vcf": strToU8(vcf) },
      /ZIP contains VCF data.*Extract.*bgzip/s,
    );
    // Recover after both rejections and cross the retired header/line/entry cutoffs
    // without constructing a large genome or exercising unrelated catalogue work.
    const extendedConsumer = consumer.replace(
      "# rsid",
      "# synthetic metadata\n".repeat(1001) + `# ${"x".repeat(70_000)}\n# rsid`,
    );
    const metadata = Object.fromEntries(
      Array.from({ length: 1001 }, (_, index) => [`__MACOSX/._note-${index}`, new Uint8Array()]),
    );
    await choose(
      "synthetic-dna.zip",
      Buffer.from(
        zipSync({
          ...metadata,
          "README.txt": strToU8("Instructions accompanying the original raw export."),
          "synthetic.txt": strToU8(extendedConsumer),
        }),
      ),
    );
    await chapter();
    await page.waitForLoadState("networkidle");
    assert.deepEqual(failures, []);
    console.log(
      "[browser] File intake verified offline: gVCF/generic gzip, DNA ZIP beyond former header/line/entry limits, actionable ZIP rejections and retry",
    );
  } finally {
    await context.close();
  }
}
